  header .right{gap:12px;min-width:var(--sidebar-w);justify-content:flex-end}
  .pill{
    padding:6px 10px;border-radius:20px;background:#f0f0f0;font-size:12px;color:#666
  }
  .icon-btn{
    width:32px;height:32px;border-radius:8px;border:1px solid var(--soft-border);
    display:flex;align-items:center;justify-content:center;background:#fff;cursor:pointer;
    transition:background .15s,border-color .15s,transform .05s;
  }
  .icon-btn:hover{background:#fafafa}
  .icon-btn:active{transform:scale(.98)}
  .icon{display:block;width:18px;height:18px;object-fit:contain}
  .search{
