  }
  .cta-row{display:flex;gap:12px;justify-content:center;align-items:center}
  .btn-primary{
    background:#fff;color:#111;border:0;padding:10px 18px;border-radius:8px;font-weight:600;cursor:pointer
  }
  .btn-link{color:#fff;opacity:.9;text-decoration:underline;cursor:pointer}
  /* Mini player strip (header, right side) */
  .mini{
