  .mini .title{font-size:12px;color:#333;max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  /* Fullscreen player */
  .player{
    position:fixed;inset:0;display:none;flex-direction:column;background:linear-gradient(135deg,#7a005e,#b1006d,#d11a6b);
    color:#fff;z-index:20;
  }
  .player.show{display:flex}
  .player .top{
    height:56px;display:flex;align-items:center;padding:0 18px;color:#f3f3f3
  }
  .player .close{font-size:22px;line-height:1;padding:6px 10px;border-radius:8px;cursor:pointer}
  .player .close:hover{background:rgba(255,255,255,.1)}
  .player .content{
    flex:1;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;padding:20px
  }
  .album{
    width:540px;height:540px;border-radius:16px;box-shadow:0 35px 60px rgba(0,0,0,.35);object-fit:cover
  }
  .track-meta{
    width:min(820px,90%);margin-top:12px
  }
  .title-main{font-weight:700}
  .subtitle{opacity:.85}
  .controls{
    width:min(820px,90%);
    display:flex;align-items:center;justify-content:center;gap:18px;margin-top:12px
  }
  .control{
    width:44px;height:44px;border-radius:12px;border:1px solid rgba(255,255,255,.35);
    display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.12);cursor:pointer
  }
  .control:hover{background:rgba(255,255,255,.18)}
  .control img{width:18px;height:18px;filter:invert(1)}
  .progress{
    width:min(820px,90%);
    margin:16px auto 0;
  }
  .bar{
    height:4px;background:rgba(255,255,255,.35);border-radius:3px;position:relative;overflow:hidden
  }
  .bar .fill{
    position:absolute;left:0;top:0;bottom:0;background:#fff;width:0%
  }
  .time-row{
    display:flex;justify-content:space-between;font-size:12px;color:#f7f7f7;margin-top:6px;opacity:.9
  }
  /* Utility */
  .btn{cursor:pointer}
  /* Scroll aesthetics inside main */
  main::-webkit-scrollbar,aside::-webkit-scrollbar{width:10px;height:10px}
  main::-webkit-scrollbar-thumb,aside::-webkit-scrollbar-thumb{background:#d7d7d7;border-radius:8px}
  main::-webkit-scrollbar-track,aside::-webkit-scrollbar-track{background:transparent}
  /* Make things roughly match 1920x944 proportions */
  @media (max-width:1400px){
    .album{width:420px;height:420px}
  }
</style>
</head>
